mapper.select:
WITH DailySummaries AS ( SELECT order_date, SUM(total_amount) AS dailyTotalSales, COUNT(*) AS dailyTotalOrders FROM orders WHERE status = 'PAID' AND order_date BETWEEN #{startDate} AND #{endDate}
AND branch_code = #{branchCode}
GROUP BY order_date ) SELECT ds.order_date AS saleDate, ds.dailyTotalSales AS totalSales, ds.dailyTotalOrders AS totalOrders, SUM(ds.dailyTotalSales) OVER (ORDER BY ds.order_date) AS cumulativeSales FROM DailySummaries ds ORDER BY ds.order_date ASC;

SELECT HOUR(created_at) AS hour, SUM(total_amount) AS totalSales, COUNT(*) AS totalOrders FROM orders WHERE status = 'PAID' AND order_date = #{targetDate}
AND branch_code = #{branchCode}
GROUP BY HOUR(created_at) ORDER BY hour ASC;

SELECT r.name AS menuName, SUM(om.qty) AS quantity, SUM(om.line_total_amount) AS totalSales FROM orders o JOIN order_menu om ON o.order_id = om.order_id JOIN recipe r ON om.recipe_code = r.recipe_code WHERE o.status = 'PAID' AND o.order_date = #{targetDate}
AND o.branch_code = #{branchCode}
GROUP BY r.name ORDER BY totalSales DESC;
